export default {
  name: "cbdetial",
  props: ['fromValue', 'isShow', 'erpUnits'],
  data() {
    return {};
  },
  mounted() {

  },
  methods: {
    getStatusName(status) {
      if (status == '0') {
        return '正常';
      }
      return '异常'
    },
    getSwerkName(swerk) {
      if (swerk && this.erpUnits) {
        let fItem = this.erpUnits.find(a => a.code == swerk);
        if (fItem) {
          return fItem.name;
        }
      }
      return null;
    },
  },
}
